-- pgTAP: personal API tokens (A86, RRR-131, finding A65-004, Section 4.5.6 personal settings item 15) and the
-- developer.personal_tokens setting that allows them. Secrets are generated by the database at run time.
begin;
create extension if not exists pgtap with schema extensions;
set search_path = extensions, public;
\ir 0300_domain_world.psql

select plan(33);

create temporary table tok (key text primary key, id uuid, secret text);
grant select, insert on tok to public;

-- The org setting decides -------------------------------------------------------------------------------------------
select pg_temp.as_user('dave');
select throws_ok($$select * from app.create_personal_access_token(pg_temp.id('org_a'), 'Laptop', array['work'], now() + interval '30 days')$$,
  'XR001', 'personal_tokens_off: Your organization does not allow personal API tokens.',
  'with developer.personal_tokens off (the default) a member cannot create a token');

select throws_ok($$select app.set_setting(pg_temp.id('org_a'), 'developer.personal_tokens', 'Organization', pg_temp.id('org_a'), p_value_boolean => true)$$,
  '42501', null, 'a member cannot turn personal tokens on');

select is(app.org_allows_personal_tokens(pg_temp.id('org_a')), false, 'Atlas reads the org as not allowing tokens');

select pg_temp.as_user('bob');
select lives_ok($$select app.set_setting(pg_temp.id('org_a'), 'developer.personal_tokens', 'Organization', pg_temp.id('org_a'), p_value_boolean => true)$$,
  'an admin with org.api_keys.manage allows personal tokens');

select pg_temp.as_user('dave');
select is(app.org_allows_personal_tokens(pg_temp.id('org_a')), true, 'a member now reads the org as allowing tokens');
select is((select string_agg(org_name, ',') from app.my_orgs_allowing_personal_tokens()), 'Northwind Live',
  'and lists it among their orgs that allow them');
select pg_temp.as_user('xavier');
select is(app.org_allows_personal_tokens(pg_temp.id('org_a')), false, 'someone outside the org learns nothing');

-- Creating a token ---------------------------------------------------------------------------------------------------
select pg_temp.as_user('dave');
select throws_ok($$select * from app.create_personal_access_token(pg_temp.id('org_a'), 'Laptop', array['org'], now() + interval '30 days')$$,
  'XR001', 'personal_token_scope_not_held: You hold no capability in org, so a token cannot use it.',
  'a token cannot reach a capability group its person does not hold');
select throws_ok($$select * from app.create_personal_access_token(pg_temp.id('org_a'), 'Laptop', array['work'], now() + interval '2 years')$$,
  'XR001', 'personal_token_expiry: Set the expiry after now and at most one year ahead.', 'the expiry is at most one year ahead');
select throws_ok($$select * from app.create_personal_access_token(pg_temp.id('org_a'), 'Laptop', array[]::text[], now() + interval '30 days')$$,
  'XR001', 'personal_token_scopes: Choose at least one area the token may use.', 'a token needs a scope');
select throws_ok($$select * from app.create_personal_access_token(pg_temp.id('org_a'), '  ', array['work'], now() + interval '30 days')$$,
  'XR001', 'personal_token_name: Name the token in 1 to 200 characters.', 'a token needs a name');

insert into tok select 'dave', t.personal_access_token_id, t.secret
from app.create_personal_access_token(pg_temp.id('org_a'), 'Laptop scripts', array['work', 'projects', 'work'], now() + interval '90 days') t;
select matches((select secret from tok where key = 'dave'), '^xos_pat_[0-9a-f]{48}$', 'the secret is returned once, xos_pat_ and 48 hex digits');
select is((select prefix from app.personal_access_tokens where id = (select id from tok where key = 'dave')),
  (select left(secret, 16) from tok where key = 'dave'), 'the visible prefix is the start of the secret');
select throws_ok($$select secret_hash from app.personal_access_tokens$$, '42501', null, 'the hash is never readable');
select is((select string_agg(scope, ',' order by scope) from app.personal_access_token_scopes
           where personal_access_token_id = (select id from tok where key = 'dave')), 'projects,work',
  'scopes are one row per capability group, duplicates collapse');
select throws_ok($$insert into app.personal_access_tokens (org_id, person_id, name, prefix, secret_hash, expires_at)
  values (pg_temp.id('org_a'), pg_temp.id('dave'), 'x', 'xos_pat_00000000', extensions.digest('x', 'sha256'), now() + interval '1 day')$$,
  '42501', null, 'tokens are created only through the RPC');

-- Who sees them -------------------------------------------------------------------------------------------------------
select pg_temp.as_user('erin');
select is((select count(*)::integer from app.personal_access_tokens), 0, 'another member does not see the token');
select pg_temp.as_user('bob');
select is((select count(*)::integer from app.personal_access_tokens where person_id = pg_temp.id('dave')), 1,
  'an admin with org.api_keys.manage sees every token of the org');
select pg_temp.as_user('xavier');
select is((select count(*)::integer from app.personal_access_tokens), 0, 'no cross-tenant reads');

-- Exchange for the API -----------------------------------------------------------------------------------------------
select pg_temp.as_platform();
select is((select count(*)::integer from app.audit_events where org_id = pg_temp.id('org_a')
           and action = 'personal_access_token.created' and subject_id = (select id from tok where key = 'dave')), 1,
  'creating a token is audited');
select is((select concat_ws('|', case when e.user_id = pg_temp.id('dave_user') then 'dave' end, array_to_string(e.scopes, ','), coalesce(e.service_account_id::text, 'none'))
           from app.exchange_api_key((select secret from tok where key = 'dave')) e), 'dave|projects,work|none',
  'the exchange resolves the token to its person''s sign-in with its scopes');
select isnt((select last_used_at from app.personal_access_tokens where id = (select id from tok where key = 'dave')), null,
  'the exchange records last use');
select is((select count(*)::integer from app.exchange_api_key('xos_pat_' || repeat('0', 48))), 0, 'an unknown token resolves to nothing');

update app.setting_values set value_boolean = false
where org_id = pg_temp.id('org_a') and setting_key = 'developer.personal_tokens' and deleted_at is null;
select is((select count(*)::integer from app.exchange_api_key((select secret from tok where key = 'dave'))), 0,
  'turning developer.personal_tokens off stops every token at the next exchange');
update app.setting_values set value_boolean = true
where org_id = pg_temp.id('org_a') and setting_key = 'developer.personal_tokens' and deleted_at is null;
select is((select count(*)::integer from app.exchange_api_key((select secret from tok where key = 'dave'))), 1,
  'and turning it back on restores them');

-- Revoking ------------------------------------------------------------------------------------------------------------
select pg_temp.as_user('erin');
select throws_ok($$select app.revoke_personal_access_token((select id from tok where key = 'dave'))$$, '42501', null,
  'another member cannot revoke the token');

select pg_temp.as_user('dave');
select lives_ok($$select app.revoke_personal_access_token((select id from tok where key = 'dave'))$$, 'the owner revokes the token');
select throws_ok($$select app.revoke_personal_access_token((select id from tok where key = 'dave'))$$, 'XR001',
  'personal_token_revoked: This token is already revoked.', 'a revoked token stays revoked');
insert into tok select 'dave2', t.personal_access_token_id, t.secret
from app.create_personal_access_token(pg_temp.id('org_a'), 'CI', array['work'], now() + interval '30 days') t;

select pg_temp.as_user('bob');
select lives_ok($$select app.revoke_personal_access_token((select id from tok where key = 'dave2'))$$,
  'an admin revokes a member''s token');

select pg_temp.as_platform();
select is((select count(*)::integer from app.exchange_api_key((select secret from tok where key = 'dave'))), 0,
  'a revoked token resolves to nothing');
select is((select count(*)::integer from app.audit_events where org_id = pg_temp.id('org_a') and action = 'personal_access_token.revoked'), 2,
  'revoking is audited');
select is((select revoked_by from app.personal_access_tokens where id = (select id from tok where key = 'dave2')), pg_temp.id('bob'),
  'the token records who revoked it');

-- Leaving the org ends the token -------------------------------------------------------------------------------------
select pg_temp.as_user('dave');
insert into tok select 'dave3', t.personal_access_token_id, t.secret
from app.create_personal_access_token(pg_temp.id('org_a'), 'Report sync', array['reports'], now() + interval '30 days') t;
select pg_temp.as_platform();
update app.memberships set deleted_at = now() where id = pg_temp.id('dave@org_a');
select is((select count(*)::integer from app.exchange_api_key((select secret from tok where key = 'dave3'))), 0,
  'a person no longer a member cannot use their token');

select * from finish();
rollback;
